describe('listing conversations', () => {
  it('answers list_sessions for the session user with ISO dates, forwarding limit and before, and answers empty when listFor is absent', async () => {
    const orchestrator = {} as ChatOrchestrator;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const listingStore = {
      listFor: (userId: string | number, options?: SessionListOptions) => {
        seen.push({userId, options});
        return summaries;
      },
    } as unknown as SessionStore;
    const plainStore = {} as SessionStore;

    const collectFrom = async (store: SessionStore | undefined, frame: unknown): Promise<OutgoingMessage[]> => {
      const frames: OutgoingMessage[] = [];
      const socket = {
        send: (raw: string) => void frames.push(JSON.parse(raw) as OutgoingMessage),
      } as unknown as WebSocket;
      await createMessageHandler(orchestrator, store)(socket, session, frame);
      return frames;
    };

    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
    const listed = await collectFrom(listingStore, {type: 'list_sessions', limit: 10, before, userId: 'u2'});
    const bare = await collectFrom(listingStore, {type: 'list_sessions'});
    const fromPlain = await collectFrom(plainStore, {type: 'list_sessions'});
    const fromOmitted = await collectFrom(undefined, {type: 'list_sessions'});
    const expectedFrame = {
      type: 'session_list',
      sessions: [
        {
          sessionId: 's2',
          createdAt: '2026-01-01T00:00:00.000Z',
          updatedAt: '2026-01-01T00:02:00.000Z',
          entryCount: 4,
        },
      ],
    };

    expect({seen, listed, bare, fromPlain, fromOmitted}).toEqual({
      seen: [
        {userId: 'u1', options: {limit: 10, before}},
        {userId: 'u1', options: {}},
      ],
      listed: [expectedFrame],
      bare: [expectedFrame],
      fromPlain: [{type: 'session_list', sessions: []}],
      fromOmitted: [{type: 'session_list', sessions: []}],
    });
  });
});

