function handlePing(ws: WebSocket, timestamp: number): void {
  ws.send(JSON.stringify({type: 'pong', timestamp}));
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  const summaries = (await sessionStore?.listFor?.(session.userId, listOptionsFor(message))) ?? [];
  sendSessionList(ws, summaries);
}

function listOptionsFor(message: ListSessionsMessage): SessionListOptions {
  const options: SessionListOptions = {};
  if (message.limit !== undefined) options.limit = message.limit;
  if (message.before !== undefined) options.before = message.before;
  return options;
}

